// generated by AI (GitHub Copilot, DeepSeek V4 Flash Vision Exp)
// Client-side registry of known databases: labels and the last opened id.
// The server lists `*.db` files; this module only remembers non-secret
// preferences. Nothing here is ever sent to the server.

import type { DatabaseDescriptor } from './descriptor';

const DB_NAME = 'upm-registry';
const STORE = 'databases';
const META = 'meta';
const VERSION = 1;
const LAST_OPENED = 'lastOpenedId';

/** A remembered database. */
export interface StoredDatabase {
  id: string;
  label: string;
  path: string;
  lastOpenedAt: number;
}

interface MetaRecord {
  key: string;
  value: string | null;
}

/** Open (creating if needed) the registry IndexedDB database. */
function openDatabase(): Promise<IDBDatabase> {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, VERSION);
    request.onupgradeneeded = () => {
      const db = request.result;
      if (!db.objectStoreNames.contains(STORE)) {
        db.createObjectStore(STORE, { keyPath: 'id' });
      }
      if (!db.objectStoreNames.contains(META)) {
        db.createObjectStore(META, { keyPath: 'key' });
      }
    };
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error ?? new Error('IndexedDB open failed'));
  });
}

/** Run `operation` in a transaction and close the database afterwards. */
async function withStore<T>(
  storeName: string,
  mode: IDBTransactionMode,
  operation: (store: IDBObjectStore) => IDBRequest<T> | void,
): Promise<T | undefined> {
  const db = await openDatabase();
  try {
    return await new Promise<T | undefined>((resolve, reject) => {
      const tx = db.transaction(storeName, mode);
      const store = tx.objectStore(storeName);
      let request: IDBRequest<T> | void;
      try {
        request = operation(store);
      } catch (error) {
        reject(error);
        return;
      }
      tx.oncomplete = () => resolve(request ? request.result : undefined);
      tx.onerror = () => reject(tx.error);
      tx.onabort = () => reject(tx.error);
    });
  } finally {
    db.close();
  }
}

/** Remember (or update) a database by id. Unsaved databases are skipped. */
export async function remember(descriptor: DatabaseDescriptor): Promise<void> {
  if (descriptor.id === '') {
    return;
  }
  const record: StoredDatabase = {
    id: descriptor.id,
    label: descriptor.label,
    path: descriptor.path,
    lastOpenedAt: Date.now(),
  };
  await withStore(STORE, 'readwrite', (store) => store.put(record));
}

/** Forget a database (its label and last-opened marker). */
export async function forget(id: string): Promise<void> {
  await withStore(STORE, 'readwrite', (store) => store.delete(id));
  if ((await getLastOpenedId()) === id) {
    await setLastOpenedId(null);
  }
}

/** All remembered databases, most recently opened first. */
export async function listRemembered(): Promise<StoredDatabase[]> {
  const records = await withStore<StoredDatabase[]>(STORE, 'readonly', (store) => store.getAll());
  return (records ?? []).sort((a, b) => b.lastOpenedAt - a.lastOpenedAt);
}

/** The id of the database that was opened last, or null. */
export async function getLastOpenedId(): Promise<string | null> {
  const record = await withStore<MetaRecord | undefined>(META, 'readonly', (store) =>
    store.get(LAST_OPENED),
  );
  return record?.value ?? null;
}

/** Remember which database was opened last. */
export async function setLastOpenedId(id: string | null): Promise<void> {
  const record: MetaRecord = { key: LAST_OPENED, value: id };
  await withStore(META, 'readwrite', (store) => store.put(record));
}
